import { test, expect } from '@playwright/test';

test.describe('Payment Flow - Expired Promo Code', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display error message for expired promo code', async ({ page }) => {
    await page.fill(getByLabel('Promo Code'), 'EXPIREDCODE123');
    await page.click(getByRole('button', { name: 'Apply' }));
    const errorMessage = await page.getByText('This promo code has expired.');
    await expect(errorMessage).toBeVisible();
  });

  test('should not apply discount with expired promo code', async ({ page }) => {
    await page.fill(getByLabel('Promo Code'), 'EXPIREDCODE123');
    await page.click(getByRole('button', { name: 'Apply' }));
    const totalAmount = await page.getByText('Total Amount: $100');
    await expect(totalAmount).toBeVisible();
  });
});
